class SemanticCliTest {
    @TempDir Path directory;
    record Result(int code,String out,String err){}
    Result run(String... args){var out=new StringWriter();var err=new StringWriter();int code=new EvoApp(directory,new StringReader(""),new PrintWriter(out),new PrintWriter(err),false,Map.of()).execute(args);return new Result(code,out.toString(),err.toString());}
    @Test void windowsShortStoreNamesReachTheSamePublicationLookup()throws Exception {
        org.junit.jupiter.api.Assumptions.assumeTrue(System.getProperty("os.name").startsWith("Windows"));
        var root=Files.createDirectory(directory.resolve("semantic-store-long-directory-name"));Files.createDirectory(root.resolve("cas"));Files.createDirectory(root.resolve("publications"));
        var value=root.toString();if(value.matches(".*[%!&|<>^\"\\r\\n].*"))throw new IllegalArgumentException("Unsafe test shell path");
        var process=new ProcessBuilder("cmd.exe","/d","/c","for %I in (\""+value+"\") do @echo %~sI").redirectErrorStream(true).start();
        if(!process.waitFor(10,java.util.concurrent.TimeUnit.SECONDS)){process.destroyForcibly();throw new IOException("Short-path fixture timed out");}
        assertEquals(0,process.exitValue());var alias=Path.of(new String(process.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8).strip());
        org.junit.jupiter.api.Assumptions.assumeFalse(alias.equals(root),"Volume does not provide a distinct 8.3 alias");assertTrue(Files.isSameFile(alias,root));
        var longName=run("semantic","summary","--semantic-store",root.toString(),"--plan",ContentDigest.sha256Utf8("missing plan").value(),"--semantic-policy",ContentDigest.sha256Utf8("policy").value(),"--json");
        var shortName=run("semantic","summary","--semantic-store",alias.toString(),"--plan",ContentDigest.sha256Utf8("missing plan").value(),"--semantic-policy",ContentDigest.sha256Utf8("policy").value(),"--json");
        assertEquals(1,longName.code());assertFalse(longName.err().contains("SEMANTIC_STORE_UNAVAILABLE"));assertEquals(longName,shortName);
    }
    @Test void explicitSignedAuthorityEnablesQualifiedReadsAndRevocationWithholdsThem()throws Exception {
        // Protocol-only keys, empty repository and method. No native engine is certified.
        var root=directory.resolve("authenticated");var content=new StreamingContentStore(root.resolve("cas"));var tables=new SemanticTables(content,65536);var generator=KeyPairGenerator.getInstance("Ed25519");var controller=generator.generateKeyPair();var validator=generator.generateKeyPair();var tool=ContentDigest.sha256Utf8("authored-cli-root-tool");var method=new EvidenceVerifier.Method(new VersionedIdentifier("authored.cli-root","v1"),new VersionedIdentifier("polyglot.root-census","m8.4-v1"),tool,List.of("SEALED_SOURCE_MEMBERSHIP","EFFECTIVE_CONTEXT_CLOSURE","GENERATED_EXTERNAL_LINEAGE","EMBEDDED_SOURCE_MAPPING"));var verifier=new EvidenceVerifier(Map.of("controller",controller.getPublic()),Map.of("validator",validator.getPublic()),List.of(method));var inventory=ContentDigest.sha256Utf8("empty-cli-inventory");var context=EvidenceContext.forSnapshot(SnapshotIdentity.from(RepositoryIdentity.fromCanonicalCoordinate("urn:test:cli-authenticated"),inventory));var docs=tables.write(SemanticTables.Kind.DOCUMENT,Collections.emptyIterator(),()->false);var coordinator=new SemanticContextCoordinator(content,tables);var plan=coordinator.plan(context,new PolyglotInventory.Report(inventory,docs,0,0),Collections.emptyIterator(),verifier.policyIdentity(),()->false);var input=new SemanticRootCensus.Input(tables.write(SemanticTables.Kind.CENSUS,Collections.emptyIterator(),()->false),tables.write(SemanticTables.Kind.CONTEXT,Collections.emptyIterator(),()->false),docs,tool);SemanticContextCoordinator.CensusIndex indexes=()->SqliteSemanticCensusIndex.temporary(root.resolve("work"),65536);SemanticRootCensus.Accounting accounting;try(var index=indexes.open()){accounting=new SemanticRootCensus(content,tables).reconcile(plan,input,index,Optional.empty(),Set.of(),plan::policy,()->false).accounting();}
        var claim=content.put(new ByteArrayInputStream(CanonicalJson.write(SemanticRootCensus.proofPayload(plan,input,accounting)).getBytes(java.nio.charset.StandardCharsets.UTF_8)),()->false);var expected=new EvidenceVerifier.Expected(ContentDigest.sha256Utf8("launch"),ContentDigest.sha256Utf8("profile"),1,plan.identity(),SemanticRootCensus.inputClosure(plan,input),claim,method.method(),method.predicate(),tool);var receipt=new EvidenceVerifier.Receipt("execution-protected-receipt:m8.4-v1","authored-cli",1,expected.launch(),expected.profile(),ContentDigest.sha256Utf8("output"),ContentDigest.sha256Utf8("materials"),ContentDigest.sha256Utf8("termination"));var attestation=new EvidenceVerifier.Attestation("execution-protected-attestation:m8.4-v1",receipt.identity(),claim.digest(),expected.scope(),expected.inputClosure(),tool,method.method(),method.predicate(),method.requiredChecks(),true);var controllerSignature=sign("controller",receipt,controller.getPrivate());var validatorSignature=sign("validator",attestation,validator.getPrivate());var proof=verifier.verifyAccepted(expected,receipt,controllerSignature,attestation,validatorSignature,content).orElseThrow();
        var authority=directory.resolve("operator");Files.createDirectories(authority.resolve("claims"));var config=new TreeMap<String,Object>();config.put("schema","semantic-authority:m8.4-v1");config.put("controllers",Map.of("controller",Base64.getEncoder().encodeToString(controller.getPublic().getEncoded())));config.put("validators",Map.of("validator",Base64.getEncoder().encodeToString(validator.getPublic().getEncoded())));config.put("methods",List.of(method));config.put("revoked",List.of());Files.writeString(authority.resolve("authority.json"),CanonicalJson.write(config));Files.writeString(authority.resolve("claims").resolve(SemanticAuthorityStore.rootKey(plan,input).value().substring(7)+".json"),CanonicalJson.write(Map.of("schema","semantic-signed-claims:m8.4-v1","claims",Map.of("root",Map.of("expected",expected,"receipt",receipt,"controllerSignature",controllerSignature,"attestation",attestation,"validatorSignature",validatorSignature)))));var configured=new SemanticAuthorityStore(authority,content,tables,plan.policy());var result=coordinator.runWithRootCensus(plan,r->Optional.empty(),(r,o)->Map.of(),r->Optional.empty(),Optional.of(new SemanticContextCoordinator.RootCensus(input,indexes,Optional.of(proof))),Map.of(),Set.of(),plan::policy,c->{},()->false);new SemanticPublicationStore(root.resolve("publications"),content,tables,Optional.of(configured.validation(indexes))).commit(plan,result,Optional.empty(),plan::policy,()->false);
        var arguments=new ArrayList<>(List.of("semantic","summary","--semantic-store",root.toString(),"--plan",plan.identity().value(),"--semantic-policy",plan.policy().value(),"--json"));assertEquals(1,run(arguments.toArray(String[]::new)).code());arguments.addAll(List.of("--semantic-authority",authority.toString()));var shown=run(arguments.toArray(String[]::new));assertEquals(0,shown.code(),shown.err());assertTrue(shown.err().isEmpty());assertTrue(shown.out().contains("CURRENT_POLICY_VALIDATED"));assertTrue(shown.out().contains("\"complete\":true"));int policyArgument=arguments.indexOf("--semantic-policy");arguments.remove(policyArgument+1);arguments.remove(policyArgument);assertEquals(0,run(arguments.toArray(String[]::new)).code());config.put("revoked",List.of(proof.identity()));Files.writeString(authority.resolve("authority.json"),CanonicalJson.write(config));assertEquals(1,run(arguments.toArray(String[]::new)).code());
    }
    private static EvidenceVerifier.SignatureEnvelope sign(String key,Object payload,PrivateKey privateKey)throws Exception {var signature=Signature.getInstance("Ed25519");signature.initSign(privateKey);signature.update(CanonicalJson.write(Map.of("keyId",key,"payload",payload)).getBytes(java.nio.charset.StandardCharsets.UTF_8));return new EvidenceVerifier.SignatureEnvelope(key,Base64.getEncoder().encodeToString(signature.sign()));}
    @Test void cliAndCanonicalServiceExposeTheSameWithheldRootWithoutExecutingAnything()throws Exception{
        var root=directory.resolve("semantic");var content=new StreamingContentStore(root.resolve("cas"));var tables=new SemanticTables(content,65536);var inventory=ContentDigest.sha256Utf8("empty semantic fixture");var context=EvidenceContext.forSnapshot(SnapshotIdentity.from(RepositoryIdentity.fromCanonicalCoordinate("urn:test:semantic-cli"),inventory));var entries=tables.write(SemanticTables.Kind.DOCUMENT,Collections.emptyIterator(),()->false);var policy=ContentDigest.sha256Utf8("operator policy");var coordinator=new SemanticContextCoordinator(content,tables);var plan=coordinator.plan(context,new PolyglotInventory.Report(inventory,entries,0,0),Collections.emptyIterator(),policy,()->false);var result=coordinator.run(plan,r->Optional.empty(),r->Map.of(),Map.of(),Set.of(),()->policy,c->{},()->false);var store=new SemanticPublicationStore(root.resolve("publications"),content,tables);store.commit(plan,result,Optional.empty(),()->policy,()->false);
        var shown=run("semantic","summary","--semantic-store",root.toString(),"--plan",plan.identity().value(),"--semantic-policy",policy.value(),"--json");assertEquals(3,shown.code(),shown.err());assertTrue(shown.err().isEmpty());var envelope=GraphJson.object(GraphJson.read(shown.out(),GraphJson.Limits.defaults()));assertEquals(SemanticQueryService.VERSION,envelope.get("apiVersion"));assertEquals(CanonicalJson.write(store.queries(()->policy).summary(plan.identity(),()->false)),CanonicalJson.write(envelope.get("data")));assertTrue(shown.out().contains("ROOT_SOURCE_CONTEXT_CENSUS_METHOD_UNQUALIFIED"));assertTrue(shown.out().contains("\"complete\":false"));
        var rootGaps=run("semantic","root-gaps","--semantic-store",root.toString(),"--plan",plan.identity().value(),"--semantic-policy",policy.value(),"--json");assertEquals(3,rootGaps.code(),rootGaps.err());assertTrue(rootGaps.out().contains("ROOT_SOURCE_CONTEXT_CENSUS_METHOD_UNQUALIFIED"));assertEquals(2,run("semantic","root-gaps","--semantic-store",root.toString(),"--plan",plan.identity().value(),"--semantic-policy",policy.value(),"--context-key","forbidden","--json").code());
        var page=run("semantic","contexts","--semantic-store",root.toString(),"--plan",plan.identity().value(),"--semantic-policy",policy.value(),"--json");assertEquals(3,page.code(),page.err());assertTrue(page.out().contains("\"items\":[]"));var revoked=run("semantic","summary","--semantic-store",root.toString(),"--plan",plan.identity().value(),"--semantic-policy",ContentDigest.sha256Utf8("revoked").value(),"--json");assertEquals(1,revoked.code());assertTrue(revoked.out().isEmpty());
    }
    @Test void helpAndMissingStoresNeverProvisionAWorkerOrCreateAStore(){
        assertEquals(0,run("semantic","--help").code());var absent=directory.resolve("absent");var shown=run("semantic","summary","--semantic-store",absent.toString(),"--plan",ContentDigest.sha256Utf8("plan").value(),"--semantic-policy",ContentDigest.sha256Utf8("policy").value(),"--json");assertEquals(1,shown.code());assertFalse(Files.exists(absent));
    }
    @Test void answerHistoryAndCurrentPagesKeepTheirExactContinuationScope()throws Exception{
        var root=directory.resolve("answers");var content=new StreamingContentStore(root.resolve("cas"));var tables=new SemanticTables(content,65536);var inventory=ContentDigest.sha256Utf8("authored protocol fixture");var context=EvidenceContext.forSnapshot(SnapshotIdentity.from(RepositoryIdentity.fromCanonicalCoordinate("urn:test:semantic-cli-answers"),inventory));var empty=tables.write(SemanticTables.Kind.DOCUMENT,Collections.emptyIterator(),()->false);var emptyCensus=tables.write(SemanticTables.Kind.CENSUS,Collections.emptyIterator(),()->false);var source=content.put(new ByteArrayInputStream("authored protocol bytes".getBytes(java.nio.charset.StandardCharsets.UTF_8)),()->false);var policy=ContentDigest.sha256Utf8("unqualified query policy");var prototype=new LanguageSemanticRequest(context,inventory,"root","app","main","default","protocolfixture","0",empty,emptyCensus,source,new VersionedIdentifier("authored.query","v1"),ContentDigest.sha256Utf8("tool"),policy,ContentDigest.sha256Utf8("work"));var documents=tables.write(SemanticTables.Kind.DOCUMENT,List.of(new SemanticTables.Row(SemanticTables.Kind.DOCUMENT,"doc",prototype.scope(),Map.of("content",source))).iterator(),()->false);var questions=new ArrayList<SemanticTables.Row>();var emissions=new ArrayList<SemanticTables.Row>();
        for(String category:LanguageProfile.requiredCategories()){var question=new SemanticTables.Row(SemanticTables.Kind.CENSUS,category,prototype.scope(),Map.of("document","doc","category",category));questions.add(question);emissions.add(new SemanticTables.Row(SemanticTables.Kind.OBSERVATION,category,prototype.scope(),Map.of("obligation",question.identity().value(),"status",Set.of("A01","A11","A12").contains(category)?"RESOLVED":"NOT_APPLICABLE","targets",List.of())));}
        var request=new LanguageSemanticRequest(context,inventory,"root","app","main","default","protocolfixture","0",documents,tables.write(SemanticTables.Kind.CENSUS,questions.iterator(),()->false),source,prototype.provider(),prototype.tool(),policy,prototype.workPolicy());var output=tables.write(SemanticTables.Kind.OBSERVATION,emissions.iterator(),()->false);var coordinator=new SemanticContextCoordinator(content,tables);var plan=coordinator.plan(context,new PolyglotInventory.Report(inventory,documents,1,0),List.of(new SemanticContextCoordinator.Selection("captured",request)).iterator(),policy,()->false);var result=coordinator.run(plan,r->Optional.of((input,cancel)->output),r->Map.of(),Map.of(),Set.of(),()->policy,c->{},()->false);new SemanticPublicationStore(root.resolve("publications"),content,tables).commit(plan,result,Optional.empty(),()->policy,()->false);
        var base=new ArrayList<>(List.of("semantic","answers","--semantic-store",root.toString(),"--plan",plan.identity().value(),"--semantic-policy",policy.value(),"--context-key","captured","--json","--limit","1"));var first=run(base.toArray(String[]::new));assertEquals(3,first.code(),first.err());var data=GraphJson.object(GraphJson.object(GraphJson.read(first.out(),GraphJson.Limits.defaults())).get("data"));assertEquals(1,GraphJson.array(data.get("items")).size());var cursor=CanonicalJson.write(data.get("continuation"));assertTrue(cursor.contains("\"rows\":\"1\""));
        var continued=new ArrayList<>(base);continued.addAll(List.of("--cursor",cursor));assertEquals(3,run(continued.toArray(String[]::new)).code());for(String view:List.of("HISTORY","CONFLICTS")){var args=new ArrayList<>(base);args.addAll(List.of("--answer-view",view));assertEquals(3,run(args.toArray(String[]::new)).code());}continued.addAll(List.of("--answer-view","HISTORY"));assertEquals(1,run(continued.toArray(String[]::new)).code());
    }
}
